                else {
                    X_value = 10;
                    ways *= (i == 0) ? 9 : 10;
                }
            }
        }
        return ways;
    }

    static int getDigit(char[] arr, int pos) {
        if (arr[pos] == '_' || arr[pos] == 'X') return -1;
        return Character.getNumericValue(arr[pos]);
    }
